Here is the commit message:
pds_core: Prevent health thread from running during
 reset/remove

The PCIe reset handlers can run at the same time as the
health thread. This can cause the health thread to
stomp on the PCIe reset. Fix this by preventing the
health thread from running while a PCIe reset is happening.

As part of this use timer_shutdown_sync() during reset and
remove to make sure the timer doesn't ever get rearmed.

Fixes: ffa55858330f ("pds_core: implement pci reset handlers")
Signed-off-by: Brett Creeley <brett.creeley@amd.com>
Reviewed-by: Shannon Nelson <shannon.nelson@amd.com>
Reviewed-by: Przemek Kitszel <przemyslaw.kitszel@intel.com>
Link: https://lore.kernel.org/r/20240129234035.69802-2-brett.creeley@amd.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug arises from the potential for the health thread to execute concurrently with PCIe reset handlers, leading to race conditions where the health thread could interfere with the reset process, potentially causing instability or incorrect behavior in the system. This situation occurs because both the health thread and the PCIe reset handlers can be triggered simultaneously, resulting in the health thread "stomping" on the reset operations.

Here is the patch:

 static int pdsc_init_pf(struct pdsc *pdsc)
 {
 	struct devlink_health_reporter *hr;
 	char wq_name[PDSC_WQ_NAME_LEN];
 	struct devlink *dl;
 	int err;

 	pcie_print_link_status(pdsc->pdev);

 	err = pci_request_regions(pdsc->pdev, PDS_CORE_DRV_NAME);
 	if (err) {
 		dev_err(pdsc->dev, "Cannot request PCI regions: %pe\n",
 			ERR_PTR(err));
 		return err;
 	}

 	err = pdsc_map_bars(pdsc);
 	if (err)
 		goto err_out_release_regions;

 	/* General workqueue and timer, but don't start timer yet */
 	snprintf(wq_name, sizeof(wq_name), "%s.%d", PDS_CORE_DRV_NAME, pdsc->uid);
 	pdsc->wq = create_singlethread_workqueue(wq_name);
 	INIT_WORK(&pdsc->health_work, pdsc_health_thread);
 	timer_setup(&pdsc->wdtimer, pdsc_wdtimer_cb, 0);
 	pdsc->wdtimer_period = PDSC_WATCHDOG_SECS * HZ;

 	mutex_init(&pdsc->devcmd_lock);
 	mutex_init(&pdsc->config_lock);
 	spin_lock_init(&pdsc->adminq_lock);

 	mutex_lock(&pdsc->config_lock);
 	set_bit(PDSC_S_FW_DEAD, &pdsc->state);

 	err = pdsc_setup(pdsc, PDSC_SETUP_INIT);
 	if (err) {
 		mutex_unlock(&pdsc->config_lock);
 		goto err_out_unmap_bars;
 	}

 	err = pdsc_start(pdsc);
 	if (err) {
 		mutex_unlock(&pdsc->config_lock);
 		goto err_out_teardown;
 	}

 	mutex_unlock(&pdsc->config_lock);

 	dl = priv_to_devlink(pdsc);
 	devl_lock(dl);
 	err = devl_params_register(dl, pdsc_dl_params,
 				   ARRAY_SIZE(pdsc_dl_params));
 	if (err) {
 		devl_unlock(dl);
 		dev_warn(pdsc->dev, "Failed to register devlink params: %pe\n",
 			 ERR_PTR(err));
 		goto err_out_stop;
 	}

 	hr = devl_health_reporter_create(dl, &pdsc_fw_reporter_ops, 0, pdsc);
 	if (IS_ERR(hr)) {
 		devl_unlock(dl);
 		dev_warn(pdsc->dev, "Failed to create fw reporter: %pe\n", hr);
 		err = PTR_ERR(hr);
 		goto err_out_unreg_params;
 	}
 	pdsc->fw_reporter = hr;

 	devl_register(dl);
 	devl_unlock(dl);

 	/* Lastly, start the health check timer */
 	mod_timer(&pdsc->wdtimer, round_jiffies(jiffies + pdsc->wdtimer_period));

 	return 0;

 err_out_unreg_params:
 	devlink_params_unregister(dl, pdsc_dl_params,
 				  ARRAY_SIZE(pdsc_dl_params));
 err_out_stop:
 	pdsc_stop(pdsc);
 err_out_teardown:
 	pdsc_teardown(pdsc, PDSC_TEARDOWN_REMOVING);
 err_out_unmap_bars:
-	del_timer_sync(&pdsc->wdtimer);
+	timer_shutdown_sync(&pdsc->wdtimer);
 	if (pdsc->wq)
 		destroy_workqueue(pdsc->wq);
 	mutex_destroy(&pdsc->config_lock);
 	mutex_destroy(&pdsc->devcmd_lock);
 	pci_free_irq_vectors(pdsc->pdev);
 	pdsc_unmap_bars(pdsc);
 err_out_release_regions:
 	pci_release_regions(pdsc->pdev);

 	return err;
 }


 static void pdsc_remove(struct pci_dev *pdev)
 {
 	struct pdsc *pdsc = pci_get_drvdata(pdev);
 	struct devlink *dl;

 	/* Unhook the registrations first to be sure there
 	 * are no requests while we're stopping.
 	 */
 	dl = priv_to_devlink(pdsc);
 	devl_lock(dl);
 	devl_unregister(dl);
 	if (!pdev->is_virtfn) {
 		if (pdsc->fw_reporter) {
 			devl_health_reporter_destroy(pdsc->fw_reporter);
 			pdsc->fw_reporter = NULL;
 		}
 		devl_params_unregister(dl, pdsc_dl_params,
 				       ARRAY_SIZE(pdsc_dl_params));
 	}
 	devl_unlock(dl);

 	if (pdev->is_virtfn) {
 		struct pdsc *pf;

 		pf = pdsc_get_pf_struct(pdsc->pdev);
 		if (!IS_ERR(pf)) {
 			pdsc_auxbus_dev_del(pdsc, pf);
 			pf->vfs[pdsc->vf_id].vf = NULL;
 		}
 	} else {
 		/* Remove the VFs and their aux_bus connections before other
 		 * cleanup so that the clients can use the AdminQ to cleanly
 		 * shut themselves down.
 		 */
 		pdsc_sriov_configure(pdev, 0);

-		del_timer_sync(&pdsc->wdtimer);
+		timer_shutdown_sync(&pdsc->wdtimer);
 		if (pdsc->wq)
 			destroy_workqueue(pdsc->wq);

 		mutex_lock(&pdsc->config_lock);
 		set_bit(PDSC_S_STOPPING_DRIVER, &pdsc->state);

 		pdsc_stop(pdsc);
 		pdsc_teardown(pdsc, PDSC_TEARDOWN_REMOVING);
 		mutex_unlock(&pdsc->config_lock);
 		mutex_destroy(&pdsc->config_lock);
 		mutex_destroy(&pdsc->devcmd_lock);

 		pci_free_irq_vectors(pdev);
 		pdsc_unmap_bars(pdsc);
 		pci_release_regions(pdev);
 	}

 	pci_disable_device(pdev);

 	ida_free(&pdsc_ida, pdsc->uid);
 	pdsc_debugfs_del_dev(pdsc);
 	devlink_free(dl);
 }

+static void pdsc_stop_health_thread(struct pdsc *pdsc)
+{
+	timer_shutdown_sync(&pdsc->wdtimer);
+	if (pdsc->health_work.func)
+		cancel_work_sync(&pdsc->health_work);
+}
+
+static void pdsc_restart_health_thread(struct pdsc *pdsc)
+{
+	timer_setup(&pdsc->wdtimer, pdsc_wdtimer_cb, 0);
+	mod_timer(&pdsc->wdtimer, jiffies + 1);
+}
+
 void pdsc_reset_prepare(struct pci_dev *pdev)
 {
 	struct pdsc *pdsc = pci_get_drvdata(pdev);

+	pdsc_stop_health_thread(pdsc);
 	pdsc_fw_down(pdsc);

 	pci_free_irq_vectors(pdev);
 	pdsc_unmap_bars(pdsc);
 	pci_release_regions(pdev);
 	pci_disable_device(pdev);
 }

 void pdsc_reset_done(struct pci_dev *pdev)
 {
 	struct pdsc *pdsc = pci_get_drvdata(pdev);
 	struct device *dev = pdsc->dev;
 	int err;

 	err = pci_enable_device(pdev);
 	if (err) {
 		dev_err(dev, "Cannot enable PCI device: %pe\n", ERR_PTR(err));
 		return;
 	}
 	pci_set_master(pdev);

 	if (!pdev->is_virtfn) {
 		pcie_print_link_status(pdsc->pdev);

 		err = pci_request_regions(pdsc->pdev, PDS_CORE_DRV_NAME);
 		if (err) {
 			dev_err(pdsc->dev, "Cannot request PCI regions: %pe\n",
 				ERR_PTR(err));
 			return;
 		}

 		err = pdsc_map_bars(pdsc);
 		if (err)
 			return;
 	}

 	pdsc_fw_up(pdsc);
+	pdsc_restart_health_thread(pdsc);
 }



